//! The marks a pick shows: Claude Code's and Codex's, Codicons' drawings (CC BY 4.0, see
//! CONTRIBUTING.md's licenses), filled on their
//! 16-unit grid, and Lucide's drawings for a command, an agent unknown, and the default, stroked
//! on their 24-unit grid. Each takes the text's colour.

/// The SVG of the mark of `agent`: `claude`, `codex`, `command`, `""` for the default, or any
/// other agent.
pub fn of(agent: &str) -> String {
    let (fill, grid, shapes) = match agent {
        "claude" => (true, 16, CLAUDE),
        "codex" => (true, 16, CODEX),
        "command" => (false, 24, TERMINAL),
        "" => (false, 24, DEFAULT),
        _ => (false, 24, BOT),
    };
    let paint = if fill {
        "fill=\"currentColor\""
    } else {
        "fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" \
         stroke-linejoin=\"round\""
    };
    format!(
        "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 {grid} {grid}\" {paint} \
         aria-hidden=\"true\">{shapes}</svg>"
    )
}

